{
  "name": "Gamry电化学工作站",
  "name_en": "Gamry electrochemical workstation",
  "manufacturer": "Gamry Instruments",
  "description": "一种用于电化学实验的台式电化学工作站（恒电位/恒电流仪），可施加设定的电位扫描并采集电流等响应信号，常用于循环伏安、线性扫描和电位斜坡类测试。",
  "description_en": "A bench-top electrochemical workstation (potentiostat/galvanostat) used for electrochemical experiments. It applies programmed potential scans and records response signals such as current, commonly for cyclic voltammetry, linear sweep, and potential ramp measurements.",
  "tag_hints": [
    "electrochemistry",
    "potentiostat galvanostat",
    "cyclic voltammetry",
    "linear sweep voltammetry",
    "potential ramp",
    "current acquisition"
  ],
  "actions": [
    {
      "action_name": "auto-open_connection",
      "description": "打开与电化学工作站的通信连接。",
      "description_en": "Open communication with the electrochemical workstation."
    },
    {
      "action_name": "auto-close_connection",
      "description": "关闭与电化学工作站的通信连接。",
      "description_en": "Close communication with the electrochemical workstation."
    },
    {
      "action_name": "auto-measurement_setup",
      "description": "设置测量或数据采集模式。",
      "description_en": "Set the measurement or data acquisition mode."
    },
    {
      "action_name": "auto-measure",
      "description": "启动测量，按设定的电位程序施加信号并采集电化学数据。",
      "description_en": "Start a measurement, apply the configured potential program, and acquire electrochemical data."
    },
    {
      "action_name": "auto-status",
      "description": "获取设备或当前测量状态。",
      "description_en": "Get the device or current measurement status."
    },
    {
      "action_name": "auto-dump_data",
      "description": "导出或读取已采集的测量数据。",
      "description_en": "Export or retrieve the acquired measurement data."
    },
    {
      "action_name": "auto-potential_ramp",
      "description": "执行电位斜坡扫描测量，从初始电位扫到终止电位并记录响应。",
      "description_en": "Run a potential ramp scan from the initial to the final potential and record the response."
    },
    {
      "action_name": "auto-potential_cycle",
      "description": "执行循环电位扫描测量，在设定电位范围内往返扫描多个循环并记录响应。",
      "description_en": "Run a cyclic potential scan over the specified potential range for multiple cycles and record the response."
    },
    {
      "action_name": "auto-simulate",
      "description": "模拟一次电化学测量过程或数据输出。",
      "description_en": "Simulate an electrochemical measurement process or data output."
    }
  ]
}

